#include <bits/stdc++.h>
using namespace std;

#define int long long

const int MOD = 998244353;

int bp(int x, int p)
{
    if(p==0) return 1;
    int q = bp(x, p/2);
    q *= q;
    q %= MOD;
    if(p%2)
    {
        q *= x;
        q %= MOD;
    }
    return q;
}

int mi(int x)
{
    x %= MOD;
    return bp(x, MOD-2);
}

const int MXN = 200005;

int fact[MXN]{};
int inv[MXN]{};

int nCr(int n, int r)
{
    int ans = fact[n];
    ans *= inv[r];
    ans %= MOD;
    ans *= inv[n-r];
    ans %= MOD;
    return ans;
}

