void solve()
{
    int n;
    cin>>n;
    
    vector<int> a(n+1, 0);
    
    for(int i=1; i<=n; i++)
    {
        cin>>a[i];
    }
    
    vector<int> pref(n+1, 0);
    for(int i=1; i<=n; i++)
    {
        pref[i] = pref[i-1] + mi(i);
        pref[i] %= MOD;
    }
    
    int ans = 0;
    for(int i=1; i<=n; i++)
    {
        int xx = pref[i-1] + pref[n-i];
        xx %= MOD;
        ans += xx*a[i];
        ans %= MOD;
    }
    
    cout<<ans<<"\n";
}

signed main() {
	// your code goes here
	ios::sync_with_stdio(0);
	cin.tie(0);
	
	fact[0] = 1;
	inv[0] = 1;
	for(int i=1; i<MXN; i++)
	{
	    fact[i] = fact[i-1]*i;
	    fact[i] %= MOD;
	    inv[i] = mi(fact[i]);
	}
	
	int t = 1;
	cin>>t;
	while(t--)
	{
	    solve();
	}
}
